<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { MainMenuContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: MainMenuContract & { embedded?:boolean; hideMobileTrigger?:boolean } = $props();
import { openModalDialog, modalDialogKeydown } from './modal-state.js';const uid=$props.id();let narrow=$state(false);onMount(()=>{const media=matchMedia('(max-width:767px)');const change=()=>narrow=media.matches;change();media.addEventListener('change',change);return()=>media.removeEventListener('change',change);});const expanded=control<string|null>(()=>p.expandedId,untrack(()=>p.defaultExpandedId),null,id=>p.onExpandedChange?.({id}));const mobile=control(()=>p.mobileOpen,untrack(()=>p.defaultMobileOpen),false,open=>p.onMobileOpenChange?.({open}));let root=$state<HTMLElement>();
function pathTo(items:typeof p.items,id:string|null):string[]{for(const item of items){if(item.id===id)return[item.id];const rest=item.children?pathTo(item.children,id):[];if(rest.length)return[item.id,...rest];}return[];}
const path=$derived(pathTo(p.items,expanded.value));
function active(id:string){return path.includes(id);}
function containsCurrent(item:typeof p.items[number]):boolean{return item.id===p.currentId||(item.children??[]).some(containsCurrent);}
// The narrow menu owns a native modal dialog as its mobile-content part (shared modal stack, scroll lock, focus return).
let dialog=$state<HTMLDialogElement>();let trigger=$state<HTMLButtonElement>();
$effect(()=>{const node=dialog;if(!node)return;const doc=node.ownerDocument;const active=doc.activeElement instanceof HTMLElement&&doc.activeElement!==doc.body?doc.activeElement:null;return openModalDialog(node,{doc,opener:active??untrack(()=>trigger)??null,returnFocusId:()=>p.mobileTriggerId});});
function focusTrigger(id:string|undefined){[...root?.querySelectorAll<HTMLButtonElement>('[aria-controls]')??[]].find(node=>node.getAttribute('aria-controls')===`${uid}-${id}`)?.focus();}
async function collapse(all=false){const previous=path.at(-1);const next=all?null:path.at(-2)??null;expanded.request(next);await tick();if(expanded.value===next)focusTrigger(all?pathTo(p.items,previous??null)[0]:previous);}
function escape(e:KeyboardEvent){if(!ignoredKey(e)&&e.key==='Escape'&&expanded.value){e.preventDefault();e.stopPropagation();void collapse(true);}}
</script>
{#snippet branch(item:typeof p.items[number])}<li {...owned('main-menu','item',item.children?.length&&active(item.id)?'expanded':'collapsed')}>{#if item.href}<a {...owned('main-menu','link',item.id===p.currentId&&'current')} href={item.href} aria-current={item.id===p.currentId?'page':undefined}>{item.label}</a>{:else if !item.children?.length}<span>{item.label}</span>{/if}{#if !item.children?.length&&item.description}<p {...owned('main-menu','description')}>{item.description}</p>{/if}{#if item.children?.length}<button type="button" {...owned('main-menu','trigger',active(item.id)?'expanded':'collapsed')} id={`${uid}-trigger-${item.id}`} aria-current={containsCurrent(item)?'true':undefined} aria-label={item.label} aria-controls={`${uid}-${item.id}`} aria-expanded={active(item.id)} onclick={()=>expanded.request(active(item.id)?pathTo(p.items,item.id).at(-2)??null:item.id)}>{item.label}<span {...owned('main-menu','indicator')} aria-hidden="true"></span></button><ul id={`${uid}-${item.id}`} {...owned('main-menu','submenu',active(item.id)?'expanded':'collapsed')} hidden={!active(item.id)}><li><h3 {...owned('main-menu','submenu-title')}>{item.label}</h3>{#if item.description}<p {...owned('main-menu','description')}>{item.description}</p>{/if}</li>{#each item.children as child(child.id)}{@render branch(child)}{/each}</ul>{/if}</li>{/snippet}{#snippet search()}{#if p.query!==undefined||p.onQueryChange}<label>메뉴 검색<input {...owned('main-menu','search')} type="search" value={p.query??''} oninput={e=>p.onQueryChange?.({value:e.currentTarget.value})}/></label>{/if}{/snippet}{#snippet list()}<ul {...owned('main-menu','list')}>{#each p.items as item(item.id)}{@render branch(item)}{/each}</ul>{/snippet}<nav bind:this={root} {...owned('main-menu','root')} aria-label={p.label??'메인 메뉴'} data-krds-layout={narrow?'mobile':'desktop'} onkeydown={escape}><button id={p.hideMobileTrigger||p.embedded?undefined:p.mobileTriggerId} bind:this={trigger} type="button" {...owned('main-menu','mobile-trigger')} hidden={!narrow||Boolean(p.hideMobileTrigger)||Boolean(p.embedded)} aria-expanded={mobile.value} aria-controls={`${uid}-mobile`} onclick={()=>mobile.request(true)}>{p.mobileTriggerLabel??'전체 메뉴'}</button>{#if !narrow||p.embedded}{@render search()}{@render list()}{:else if mobile.value}<dialog bind:this={dialog} id={`${uid}-mobile`} {...owned('main-menu','mobile-content','mobile-open')} role="dialog" aria-modal="true" aria-label={p.label??'메인 메뉴'} tabindex="-1" oncancel={event=>event.preventDefault()} onkeydown={event=>{escape(event);modalDialogKeydown(dialog,event,()=>mobile.request(false));}}><button type="button" {...owned('main-menu','close')} onclick={()=>mobile.request(false)}>메뉴 닫기</button><button type="button" {...owned('main-menu','back')} hidden={!expanded.value} onclick={()=>collapse()}>이전 메뉴</button>{@render search()}{@render list()}</dialog>{/if}</nav><style>dialog{margin:0;}</style>
